import json
import itertools

def solve():
    houses = [1, 2, 3, 4, 5]
    names = ["Peter", "Alice", "Bob", "Eric", "Arnold"]
    heights = ["very tall", "average", "tall", "very short", "short"]

    solutions = []

    # Iterate over permutations of names and heights
    for names_perm in itertools.permutations(names):
        pos_by_name = {name: i + 1 for i, name in enumerate(names_perm)}

        # Clue 2: Peter is directly left of Bob.
        if not (pos_by_name["Peter"] + 1 == pos_by_name["Bob"]):
            continue

        # Clue 3: Eric is somewhere to the left of Peter.
        if not (pos_by_name["Eric"] < pos_by_name["Peter"]):
            continue

        for heights_perm in itertools.permutations(heights):
            pos_by_height = {height: i + 1 for i, height in enumerate(heights_perm)}

            # Clue 1: The person who is short is in the second house.
            if pos_by_height["short"] != 2:
                continue

            # Clue 7: The person who has an average height is in the fifth house.
            if pos_by_height["average"] != 5:
                continue

            # Clue 6: The person who is short and the person who is very short are next to each other.
            if abs(pos_by_height["short"] - pos_by_height["very short"]) != 1:
                continue

            # Clue 4: The person who is very tall is directly left of Peter.
            if not (pos_by_height["very tall"] + 1 == pos_by_name["Peter"]):
                continue

            # Clue 5: Alice is directly left of the person who has an average height.
            if not (pos_by_name["Alice"] + 1 == pos_by_height["average"]):
                continue

            # If all constraints satisfied, record solution
            solutions.append((names_perm, heights_perm))

    # Assuming unique solution
    if not solutions:
        raise RuntimeError("No solution found")
    names_sol, heights_sol = solutions[0]

    # Build output JSON structure
    rows = []
    for i in range(5):
        house_num = str(i + 1)
        rows.append([house_num, names_sol[i], heights_sol[i]])

    result = {
        "solution": {
            "header": ["House", "Name", "Height"],
            "rows": rows
        }
    }
    print(json.dumps(result, ensure_ascii=False))



if __name__ == "__main__":
    solve()
